  "promptLibrary.scroll-velocity-direction-marquee.title": { ko: "스크롤 방향 마키", en: "Scroll Direction Marquee", "zh-CN": "随滚动转向的跑马灯" },
  "promptLibrary.scroll-velocity-direction-marquee.summary": { ko: "스크롤 방향에 따라 빨라지고 방향을 바꾸는 반복 문구 띠예요.", en: "A looping text ribbon that speeds up and flips direction with your scroll.", "zh-CN": "循环文字带随滚动加速并改变方向。" },
  "promptLibrary.scroll-velocity-image-skew.title": { ko: "스크롤 속도 기울임", en: "Scroll Speed Skew", "zh-CN": "滚动速度倾斜" },
