function copyOf(id: string, keywords: Readonly<Record<Locale, readonly string[]>>): PromptLibraryCopy {
  const title = PROMPT_LIBRARY_MESSAGES[promptMessageKey(id, "title")];
  const summary = PROMPT_LIBRARY_MESSAGES[promptMessageKey(id, "summary")];
  if (title === undefined || summary === undefined) throw new Error(`Prompt library copy is missing for ${id}`);
  return { title, summary, keywords };
}

export const PROMPT_LIBRARY_COPY: Readonly<Record<string, PromptLibraryCopy>> = Object.fromEntries(
  Object.entries(PROMPT_LIBRARY_KEYWORDS).map(([id, keywords]) => [id, copyOf(id, keywords)]),
);
